#include "c3_exposure.h"
#include <stdint.h>
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>

#if !C3_SHUTTER_DATASHEET_TIMING
#error "Run this with datasheet timing enabled"
#endif
static const uint16_t preview_1x[9]={1,2,4,8,16,27,54,82,163};
static const uint16_t preview_4x[9]={1,2,3,6,13,21,42,64,127};
static const uint16_t raw_0[9]={2,4,8,15,31,51,102,153,306};
static const uint16_t raw_1[9]={1,2,4,8,15,26,51,77,153};
/* Capture register values generated by c3_exposure_apply(). */
static uint8_t aec_hi, aec_lo, mode_count;
static uint8_t wr(uint8_t reg,uint8_t val)
{
    if (reg==0x08u) { aec_hi=val; ++mode_count; }
    if (reg==0x10u) { aec_lo=val; ++mode_count; }
    return 0u;
}
static uint16_t measure_shutter(uint8_t code,c3_exposure_sensor_mode_t mode)
{
    c3_exposure_t s; c3_exposure_init(&s,code,0u); c3_exposure_gain_next(&s);
    mode_count=0u;
    assert(c3_exposure_apply(&s,mode,wr));
    assert(mode_count==2u);
    return (uint16_t)((uint16_t)aec_hi*256u+aec_lo);
}
int main(void)
{
    assert(c3_exposure_estimated_row_ns(C3_EXPOSURE_PREVIEW,0u)==122333u);
    assert(c3_exposure_estimated_row_ns(C3_EXPOSURE_RAW,0u)==65333u);
    assert(c3_exposure_estimated_row_ns(C3_EXPOSURE_RAW,1u)==130667u);
    assert(c3_exposure_estimated_row_ns(C3_EXPOSURE_BMP,0u)==122333u);
    assert(c3_exposure_estimated_row_ns(C3_EXPOSURE_RAW,2u)==0u);
    for (unsigned i=0;i<9u;++i) {
        assert(c3_exposure_rows((uint8_t)i)==preview_1x[i]);
        assert(c3_exposure_rows_for_mode((uint8_t)i,C3_EXPOSURE_RAW,0u)==raw_0[i]);
        assert(c3_exposure_rows_for_mode((uint8_t)i,C3_EXPOSURE_RAW,1u)==raw_1[i]);
        assert(measure_shutter((uint8_t)i,C3_EXPOSURE_PREVIEW)==preview_1x[i]);
        assert(measure_shutter((uint8_t)i,C3_EXPOSURE_BMP)==preview_1x[i]);
        assert(measure_shutter((uint8_t)i,C3_EXPOSURE_RAW)==raw_0[i]);
    }
    assert(c3_exposure_rows(9u)==0u);
    c3_exposure_set_preview_zoom(1u);
    assert(c3_exposure_estimated_row_ns(C3_EXPOSURE_PREVIEW,0u)==157000u);
    assert(c3_exposure_estimated_row_ns(C3_EXPOSURE_BMP,0u)==122333u);
    for (unsigned i=0;i<9u;++i) {
        assert(c3_exposure_rows((uint8_t)i)==preview_4x[i]);
        assert(measure_shutter((uint8_t)i,C3_EXPOSURE_PREVIEW)==preview_4x[i]);
        /* 4x preview but saved BMP always reverts to QVGA 1x */
        assert(measure_shutter((uint8_t)i,C3_EXPOSURE_BMP)==preview_1x[i]);
    }
    c3_exposure_set_preview_zoom(0u);
    assert(c3_exposure_raw_rows(82u,0u)==154u);
    assert(c3_exposure_raw_rows(82u,1u)==77u);
    c3_exposure_set_preview_zoom(1u);
    assert(c3_exposure_raw_rows(64u,0u)==154u);
    c3_exposure_set_preview_zoom(0u);
    assert(c3_exposure_raw_rows(8191u,0u)==8191u);
    assert(c3_exposure_raw_rows(2u,2u)==0u);
    for(unsigned r=1;r<=8191;r+=43) {
        uint16_t v=c3_exposure_raw_rows((uint16_t)r,0u);
        assert(v>=1u && v<=8191u);
    }
    puts("PASS v169 datasheet model: XCLK12M PLL4 CLKRC0, QVGA/VGA rows, zoom, BMP 1x, RAW lock");
    return 0;
}
